import{z as n,x as o,o as E,c as P,q as i,j as r,D as e,d as A,s as l,S,b as s}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"IPsec 与 IKE","description":"","frontmatter":{"title":"IPsec 与 IKE","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ipsec-ike.md","filePath":"cs/ipsec-ike.md","lastUpdated":1791413859000}'),p={name:"cs/ipsec-ike.md"};function d(D,a,I,c,B,h){const t=o("Mermaid");return E(),P("div",null,[a[2]||(a[2]=i('<h1 id="ipsec-与-ike" tabindex="-1">IPsec 与 IKE <a class="header-anchor" href="#ipsec-与-ike" aria-label="Permalink to &quot;IPsec 与 IKE&quot;">​</a></h1><div class="epigraph"><p>IPsec 把 AEAD 推到 IP 层：SPD 决定哪些流要保护，SAD 里是密钥与 SPI。IKE 负责协商与认证，失败时看起来像「VPN 连不上」，其实是身份与选择器没对齐。</p><footer>—— RFC 4301；RFC 7296 IKEv2；Kent and Seo</footer></div><p>上一课<a href="/cs/ssh-keys-auth">SSH</a>保护的是一条交互会话。本课补<strong>网段之间的策略</strong>：整网段或整主机的 IP 流要按策略保护。主干网络课的内容不重写，这里收 SPD/SAD 架构与 IKEv2 的合同。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>让应用各自跑 TLS 会漏掉非 TLS 流，策略也无法统一收口。IPsec 把保护下沉到 IP 层：传输模式保护主机到主机的载荷，隧道模式由网关封装整个 IP 包对外。密钥与算法装在 SA 里，由 IKE 用 DH 与身份认证（PSK 或证书）协商建立。缺口是两处合同松弛：选择器过宽——所有端口流量共用一套 SA，一失全失；PSK 共享——一组人共用同一预共享密钥，人走钥匙不换。不是再讲 ESP 头字段百科。</p><h3 id="nat-与-udp-封装" tabindex="-1">NAT 与 UDP 封装 <a class="header-anchor" href="#nat-与-udp-封装" aria-label="Permalink to &quot;NAT 与 UDP 封装&quot;">​</a></h3><p>ESP 没有端口字段可改，遇 NAT 常被中间盒破坏，实践里通常包进 UDP（NAT-T）。封装只是穿过中间盒，不改变合同：对端身份仍必须经 IKE 认证，隧道通了不等于认证过了。</p><p><span class="marginnote">RFC 4301 架构。IKEv2 简化 IKEv1 的多轮。本课不给破 SA 的步骤。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>数据面流程：每个包先查 SPD 的选择器（源/目的/协议/端口），命中的按策略送 ESP，密钥从 SAD 里按 SPI 取出。控制面流程：IKE 先用 DH 与身份认证建 IKE SA，再在其保护下派生子 SA 给 ESP 用。与 TLS 对照：保护端点是应用对应用，还是主机/网关对网关。经验上策略冲突与旁路——某条流意外匹配了「旁路」条目——比密码套件选择更常出事。</p>',11)),(E(),r(S,null,{default:e(()=>[l(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20IKE%5B%22IKEv2%20%E8%AE%A4%E8%AF%81%E4%B8%8E%20DH%22%5D%20--%3E%20SA%5B%22SAD%20%E4%B8%AD%E7%9A%84%20SA%22%5D%0A%20%20SPD%5B%22SPD%20%E9%80%89%E6%8B%A9%E5%99%A8%22%5D%20--%3E%20ESP%5B%22ESP%20AEAD%22%5D%0A%20%20SA%20--%3E%20ESP%0A%20%20ESP%20--%3E%20IP%5B%22%E5%8F%97%E4%BF%9D%E6%8A%A4%20IP%20%E6%B5%81%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[A("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,"网络层保密把中间路径变成密文，但不自动给应用身份：网关解密后的包在内网以明文前进，应用看到的源是网关而非人。网关 VPN 常把所有远程用户汇成一个内网源地址，保护粒度到网关为止——零信任课会拆这条。下一课 WireGuard：刻意变小的另一合同。",-1)),(E(),r(S,null,{default:e(()=>[l(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20PKT%5B%22%E5%87%BA%E7%AB%99%20IP%20%E5%8C%85%22%5D%20--%3E%20SPD%7B%22%E6%9F%A5%20SPD%20%E9%80%89%E6%8B%A9%E5%99%A8%3A%20%E6%BA%90%2F%E7%9B%AE%E7%9A%84%2F%E5%8D%8F%E8%AE%AE%2F%E7%AB%AF%E5%8F%A3%22%7D%0A%20%20SPD%20--%3E%7C%22protect%22%7C%20SPI%5B%22%E6%9F%A5%20SAD%3A%20%E6%8C%89%20SPI%20%E5%8F%96%E5%AF%86%E9%92%A5%22%5D%0A%20%20SPI%20--%3E%20ESP%5B%22ESP%20%E5%B0%81%E8%A3%85%20%2B%20AEAD%20%E5%8A%A0%E5%AF%86%22%5D%0A%20%20SPD%20--%3E%7C%22bypass%22%7C%20RAW%5B%22%E5%8E%9F%E6%A0%B7%E5%8F%91%E5%87%BA%20(%E6%98%93%E9%85%8D%E9%94%99%3A%20%E8%AF%A5%E4%BF%9D%E6%8A%A4%E7%9A%84%E6%BC%8F%E4%BA%86)%22%5D%0A%20%20ESP%20--%3E%20TUN%5B%22%E9%9A%A7%E9%81%93%E6%A8%A1%E5%BC%8F%3A%20%E5%86%8D%E5%A5%97%E6%96%B0%20IP%20%E5%A4%B4%22%5D%0A%20%20IKE%5B%22IKEv2%3A%20DH%20%2B%20%E8%BA%AB%E4%BB%BD%E8%AE%A4%E8%AF%81%22%5D%20-.-%3E%7C%22%E6%B4%BE%E7%94%9F%E5%AF%86%E9%92%A5%22%7C%20SPI%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p><span class="marginnote">术语翻译：SA（安全关联）就是一条「加密合同」，写明用哪个算法、哪把密钥、保护哪条流；SPI 是合同的编号——ESP 头里只带这个 32 位编号，接收方靠它去 SAD（合同柜）里翻出对应的密钥。</span></p><p><span class="marginnote">数字实例：SPI 占 32 位，SAD 里可能有成千上万条 SA（一个大网关对每个对端、每条隧道各存多条）。收包时先从 ESP 头读出 SPI，一次哈希/查表定位 SA，才谈得上解密——没有 SPI，解密前就得先「猜」密钥，这是设计的关键一步。</span></p><p><span class="marginnote">常见误区：初学者容易以为「VPN 隧道 ping 通了」就万事大吉。隧道通只说明封装路径对，若 IKE 的身份认证没过或策略匹配了 bypass 条目，数据可能正在以明文跑，或者跑在一条没验证对端身份的「加密」通道里。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 IKEv1 的全部模式，主模式/野蛮模式的历史包袱从略。WireGuard 下一课用 Noise 与静态钥把协商收短。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SSH 保护登录会话；IPsec 按 policy 保护 IP 流。</li><li>IKE 负责认证与建 SA；SPD 决定什么必须进 ESP。</li><li>共享 PSK 与过宽选择器是常见的合同松弛。</li><li>下一课 WireGuard。</li><li>出处：RFC 4301；RFC 7296；Kent and Seo。</li></ul>',7))])}const F=n(p,[["render",d]]);export{u as __pageData,F as default};
